def discover_spawned_agents(self) -> List[AgentProfile]:
    """
    Scan workspace/agents/ and create AgentProfile for each spawned agent.

    Returns:
        List of AgentProfile objects ready for registration in AgentPool
    """
    agents = []

    if not self.agents_dir.exists():
        logger.debug(f"No agents directory at {self.agents_dir}")
        return agents

    for agent_dir in self.agents_dir.iterdir():
        if not agent_dir.is_dir():
            continue

        try:
            profile = self._load_agent_from_dir(agent_dir)
            if profile:
                agents.append(profile)
                logger.info(f"Discovered spawned agent: {profile.agent_id}")
        except Exception as e:
            logger.warning(f"Failed to load agent from {agent_dir}: {e}")

    logger.info(f"Discovered {len(agents)} spawned agents")
    return agents

def load_system_prompt(self, agent_id: str) -> Optional[str]:
    """
    Load the specialized system prompt for an agent.

    Args:
        agent_id: Agent identifier

    Returns:
        System prompt content or None if not found
    """
    prompt_file = self.agents_dir / agent_id / "system_prompt.md"

    if not prompt_file.exists():
        return None

    try:
        return prompt_file.read_text(encoding='utf-8')
    except Exception as e:
        logger.warning(f"Failed to load system prompt for {agent_id}: {e}")
        return None

def _analyze_directories(self) -> List[str]:
    """Find significant directories."""
    significant_dirs = []
    ignored = {".git", "node_modules", "__pycache__", ".venv", "venv",
               ".tox", ".pytest_cache", "dist", "build", ".next", "target"}

    try:
        for item in self.project_path.iterdir():
            if item.is_dir() and item.name not in ignored and not item.name.startswith("."):
                significant_dirs.append(item.name)
    except PermissionError:
        pass

    return sorted(significant_dirs)[:20]  # Limit to 20

def _find_key_files(self) -> List[str]:
    """Find configuration and key files."""
    key_patterns = [
        "README*", "LICENSE*", "CHANGELOG*",
        "package.json", "pyproject.toml", "setup.py", "setup.cfg",
        "Makefile", "Dockerfile", "docker-compose*",
        "requirements*.txt", "Pipfile", "Cargo.toml", "go.mod",
        "tsconfig.json", ".env.example", "*.config.js", "*.config.ts",
    ]

    found = []
    for pattern in key_patterns:
        for match in self.project_path.glob(pattern):
            if match.is_file():
                found.append(match.name)

    return sorted(set(found))[:30]  # Limit and dedupe

