def _trigger_panic(self, reason: str, details: str):
    """Déclenche le panic state"""
    if self.is_in_panic:
        return  # Already in panic

    self.is_in_panic = True
    self.panic_reason = reason

    panic_data = {
        "timestamp": datetime.utcnow().isoformat(),
        "reason": reason,
        "details": details,
        "stalemate_counter": self.stalemate_counter,
        "consecutive_errors": self.consecutive_errors
    }

    # Write panic file
    self.panic_file.write_text(json.dumps(panic_data, indent=2), encoding='utf-8')

    # Log to history
    self._log_to_history({
        "type": "PANIC",
        **panic_data
    })

def is_panicked(self) -> bool:
    """Check if system is in panic"""
    return self.is_in_panic

def get_panic_info(self) -> Optional[Dict]:
    """
    Récupère les infos de panic

    Returns:
        Panic data dict ou None
    """
    if not self.panic_file.exists():
        return None

    try:
        return json.loads(self.panic_file.read_text(encoding='utf-8'))
    except:
        return None

def _log_to_history(self, event: Dict):
    """Log event to panic history (JSONL)"""
    try:
        with open(self.panic_history, 'a', encoding='utf-8') as f:
            f.write(json.dumps(event) + '\n')
    except:
        pass  # Don't crash on logging failure

def _has_progress(self, prev_plan: Optional[List[Dict]], curr_plan: List[Dict]) -> bool:
    """Détecte si au moins une étape a changé de statut"""
    if not prev_plan:
        return False

    for i, curr_step in enumerate(curr_plan):
        if i >= len(prev_plan):
            return True  # New step added

        prev_step = prev_plan[i]
        if prev_step.get("status") != curr_step.get("status"):
            return True

    return False

def _has_completion(self, prev_plan: Optional[List[Dict]], curr_plan: List[Dict]) -> bool:
    """Détecte si au moins une étape est passée à COMPLETED"""
    if not prev_plan:
        return False

    for i, curr_step in enumerate(curr_plan):
        if i >= len(prev_plan):
            continue

        prev_step = prev_plan[i]
        if prev_step.get("status") != "COMPLETED" and curr_step.get("status") == "COMPLETED":
            return True

    return False

def _determine_status(self, turns_since_progress: int, turns_since_completion: int,
                     turns_since_creation: int, current_plan: List[Dict]) -> tuple:
    """Détermine le statut de santé"""

    # Check for ZOMBIE (most severe)
    all_pending = all(step.get("status") == "PENDING" for step in current_plan)
    if all_pending and turns_since_creation > self.zombie_threshold:
        return (
            "ZOMBIE",
            f"Plan zombie détecté: toutes les étapes PENDING depuis {turns_since_creation} tours",
            "CRITICAL: Réinitialiser le plan ou forcer une décision immédiate"
        )

    # Check for STAGNANT
    if turns_since_completion > self.stagnant_threshold:
        return (
            "STAGNANT",
            f"Plan stagnant: aucune étape complétée depuis {turns_since_completion} tours",
            "WARNING: Forcer une étape à complétion ou ajuster la stratégie"
        )

    # Check for WARNING
    if turns_since_progress > self.warning_threshold:
        return (
            "WARNING",
            f"Plan n'a pas progressé depuis {turns_since_progress} tours",
            "Vérifier si les agents sont bloqués ou si le plan doit être ajusté"
        )

    # HEALTHY
    return (
        "HEALTHY",
        "Plan progresse normalement",
        None
    )

