    # Remove common words and split
    stop_words = {
        "the", "a", "an", "to", "for", "of", "in", "on", "with", "and",
        "or", "is", "are", "be", "this", "that", "it", "we", "will",
        "should", "can", "use", "using", "try", "attempt"
    }
    words = strategy.lower().split()
