def cleanup_old_logs(workspace_path: Path, keep_days: int = 7):
    """
    Cleanup logs plus vieux que N jours

    Args:
        workspace_path: Workspace NEXUS
        keep_days: Garder logs des N derniers jours
    """
    log_dir = workspace_path / "logs"
    if not log_dir.exists():
        return

    cutoff_date = datetime.now().timestamp() - (keep_days * 86400)

    for log_file in log_dir.glob("*"):
        if log_file.is_file():
            try:
                if log_file.stat().st_mtime < cutoff_date:
                    log_file.unlink()
            except:
                pass  # Ignore cleanup errors

class MCPClientError(Exception):
    """Base exception for MCP client errors."""
    pass

class MCPConnectionError(MCPClientError):
    """Failed to connect to MCP server."""
    pass

class MCPTimeoutError(MCPClientError):
    """Request timed out."""
    pass

def close(self) -> None:
    """
    Close connection and terminate server subprocess.
    """
    # Stop reader thread
    self._reader_stop.set()

    if self._process is not None:
        try:
            # Try graceful shutdown
            if self._state.initialized:
                try:
                    self._send_request(MCPMethod.SHUTDOWN, {}, timeout=2.0)
                except Exception:
                    pass  # Ignore shutdown errors

            # Close pipes
            if self._process.stdin:
                self._process.stdin.close()
            if self._process.stdout:
                self._process.stdout.close()
            if self._process.stderr:
                self._process.stderr.close()

            # Terminate process
            self._process.terminate()
            try:
                self._process.wait(timeout=5.0)
            except subprocess.TimeoutExpired:
                self._process.kill()

        finally:
            self._process = None
            self._state = MCPClientState()

    # Wait for reader thread
    if self._reader_thread and self._reader_thread.is_alive():
        self._reader_thread.join(timeout=1.0)

@property

def is_connected(self) -> bool:
    """Check if connected to server."""
    return self._process is not None and self._process.poll() is None

@property

def _ensure_initialized(self) -> None:
    """Ensure client is initialized."""
    if not self._state.initialized:
        raise MCPClientError("Client not initialized. Call initialize() first.")

def _send_notification(self, method: str, params: Optional[Dict[str, Any]] = None) -> None:
    """
    Send a notification (no response expected).

    Args:
        method: JSON-RPC method name
        params: Notification parameters
    """
    if not self.is_connected:
        return

    # Notifications have no id
    message = json.dumps({
        "jsonrpc": "2.0",
        "method": method,
        "params": params or {},
    }) + "\n"

    try:
        self._process.stdin.write(message)
        self._process.stdin.flush()
    except (BrokenPipeError, OSError):
        pass  # Ignore notification errors

    def _reader_loop(self) -> None:
        """
        Background thread that reads responses from server stdout.
        """
        try:
            while not self._reader_stop.is_set():
                if self._process is None or self._process.stdout is None:
                    break

                # Check if process is still running
                if self._process.poll() is not None:
                    break

                try:
                    line = self._process.stdout.readline()
                    if not line:
                        break

                    line = line.strip()
                    if not line:
                        continue

                    # Parse JSON response
                    try:
                        data = json.loads(line)
                        self._response_queue.put(data)
                    except json.JSONDecodeError as e:
                        # Log but don't crash
                        pass

                except Exception as e:
                    if not self._reader_stop.is_set():
                        self._response_queue.put(MCPConnectionError(f"Reader error: {e}"))
                    break

        except Exception:
            pass  # Thread exit


