def _get_func_name(self, node: ast.Call) -> str:
    """Extract function name from a Call node."""
    if isinstance(node.func, ast.Name):
        return node.func.id
    elif isinstance(node.func, ast.Attribute):
        return node.func.attr
    return ""

def _extract_first_string_arg(self, node: ast.Call) -> str:
    """Extract the first string argument from a call (for open() analysis)."""
    if node.args:
        first_arg = node.args[0]
        # Python 3.8+ uses ast.Constant
        if isinstance(first_arg, ast.Constant) and isinstance(first_arg.value, str):
            return first_arg.value
        # Older Python uses ast.Str
        elif hasattr(ast, 'Str') and isinstance(first_arg, ast.Str):
            return first_arg.s
    return ""

def _is_parent_or_absolute_path(self, path: str) -> bool:
    """Check if a path references parent directory or is absolute."""
    if not path:
        return False

    # Absolute paths
    if path.startswith('/') or (len(path) > 1 and path[1] == ':'):
        return True

    # Parent directory references
    if path.startswith('..'):
        return True

    # Hidden parent references
    if '/../' in path or path.endswith('/..'):
        return True

    return False

def _is_sacred(self, path: Path) -> bool:
    """Check if a file is sacred (never modifiable)."""
    # Exact match
    if path.name in self.sacred_files:
        return True

    # Pattern match (e.g., .env.*)
    for pattern in self.sacred_patterns:
        if path.name.startswith(pattern):
            return True

    return False

