def from_json(cls, line: str) -> Optional["TelemetryEvent"]:
    """Parse a JSONL line into TelemetryEvent."""
    try:
        obj = json.loads(line.strip())
        timestamp_str = obj.get("timestamp", "")
        # Handle ISO format with Z suffix
        if timestamp_str.endswith("Z"):
            timestamp_str = timestamp_str[:-1]
        timestamp = datetime.fromisoformat(timestamp_str)

        return cls(
            event_type=obj.get("type", "unknown"),
            session_id=obj.get("session_id", ""),
            timestamp=timestamp,
            data=obj.get("data", {})
        )
    except (json.JSONDecodeError, ValueError, KeyError):
        return None

def _iter_events(
    self,
    since: Optional[datetime] = None,
    event_types: Optional[List[str]] = None
) -> Iterator[TelemetryEvent]:
    """
    Iterate over telemetry events with optional filtering.

    Args:
        since: Only include events after this timestamp.
        event_types: Only include these event types.

    Yields:
        TelemetryEvent objects.
    """
    if not self.telemetry_file.exists():
        return

    try:
        with open(self.telemetry_file, "r", encoding="utf-8") as f:
            for line in f:
                if not line.strip():
                    continue

                event = TelemetryEvent.from_json(line)
                if event is None:
                    continue

                # Filter by time
                if since and event.timestamp < since:
                    continue

                # Filter by type
                if event_types and event.event_type not in event_types:
                    continue

                yield event
    except (IOError, OSError):
        return

def get_event_count(self) -> int:
    """Get total number of events in telemetry file."""
    if not self.telemetry_file.exists():
        return 0

    count = 0
    try:
        with open(self.telemetry_file, "r", encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    count += 1
    except (IOError, OSError):
        pass
    return count

def _write_event(self, event_type: MetricType, data: Dict[str, Any]):
    """Write an event to the telemetry file (thread-safe)"""
    if not self.enabled:
        return

    event = {
        "type": event_type.value,
        "session_id": self.session_id,
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "data": data
    }

    with self._lock:
        try:
            with open(self.output_file, 'a', encoding='utf-8') as f:
                f.write(json.dumps(event, ensure_ascii=False) + '\n')
        except Exception as e:
            print(f"[Telemetry] Write error: {e}")

