def _parse_analysis_response(self, response: str, agent_id: str) -> Dict[str, Any]:
    """Parse agent's JSON response into analysis data."""
    import json
    import re

    # Try to extract JSON from response
    json_match = re.search(r'\{[\s\S]*\}', response)
    if not json_match:
        logger.warning(f"{agent_id} response not in JSON format, using defaults")
        return self._default_analysis_data()

    try:
        data = json.loads(json_match.group())

        # Validate and normalize
        return {
            "task_understanding": data.get("task_understanding", "Unknown"),
            "complexity_assessment": data.get("complexity_assessment", "MODERATE"),
            "proposed_approach": data.get("proposed_approach", "Unknown"),
            "required_capabilities": data.get("required_capabilities", []),
            "potential_risks": data.get("potential_risks", []),
            "confidence": float(data.get("confidence", 0.5)),
            "reasoning": data.get("reasoning", "")
        }

    except json.JSONDecodeError as e:
        logger.warning(f"JSON parse error for {agent_id}: {e}")
        return self._default_analysis_data()

def _get_skip_reason(self, comparison: AnalysisComparison) -> str:
    """Get reason for skipping debate."""
    if comparison.agreement_score >= 0.95:
        return "Near-perfect agreement (>95%)"
    elif comparison.agreement_score >= 0.9:
        return "Very high agreement (>90%)"
    elif comparison.agreement_score >= self.AGREEMENT_THRESHOLD:
        return f"High agreement ({comparison.agreement_score:.0%})"
    elif not comparison.disagreements:
        return "No significant disagreements found"
    else:
        return "Minor disagreements only"

def _check_for_duplicates(self, architecture: AgentArchitecture) -> AgentArchitecture:
    """Check for duplicate agents and remove them."""
    self.cost_estimator.record_cost("check_registry", 100)

    remaining_spawns = []
    for spec in architecture.agents_to_spawn:
        # Check if similar agent exists
        similar = self.registry.find_similar(spec.capabilities)

        if similar:
            logger.info(
                f"Found similar agent '{similar.agent_id}' for '{spec.role}' - "
                f"skipping spawn"
            )
            # Add existing agent to use list
            if similar.agent_id not in architecture.agents_to_use:
                architecture.agents_to_use.append(similar.agent_id)
        else:
            remaining_spawns.append(spec)

    architecture.agents_to_spawn = remaining_spawns

    if not remaining_spawns:
        architecture.status = "READY"
    else:
        architecture.status = "SPAWN_SUGGESTED"

    return architecture

